1	import { getTRPCErrorFromUnknown, TRPCError } from '../../error/TRPCError';
2	import { MaybePromise, Simplify } from '../../types';
3	import {
4	  createInputMiddleware,
5	  createOutputMiddleware,
6	  MiddlewareBuilder,
7	  MiddlewareFunction,
8	  MiddlewareResult,
9	} from '../middleware';
10	import { inferParser, Parser } from '../parser';
11	import {
12	  AnyMutationProcedure,
13	  AnyProcedure,
14	  AnyQueryProcedure,
15	  AnySubscriptionProcedure,
16	  Procedure,
17	  ProcedureParams,
18	} from '../procedure';
19	import { ProcedureType } from '../types';
20	import { AnyRootConfig } from './config';
21	import { getParseFn } from './getParseFn';
22	import { mergeWithoutOverrides } from './mergeWithoutOverrides';
23	import {
24	  DefaultValue as FallbackValue,
25	  middlewareMarker,
26	  Overwrite,
27	  OverwriteKnown,
28	  ResolveOptions,
29	  UnsetMarker,
30	} from './utils';
31	
32	type CreateProcedureReturnInput<
33	  TPrev extends ProcedureParams,
34	  TNext extends ProcedureParams,
35	> = ProcedureBuilder<{
36	  _config: TPrev['_config'];
37	  _meta: TPrev['_meta'];
38	  _ctx_out: Overwrite<TPrev['_ctx_out'], TNext['_ctx_out']>;
39	  _input_in: UnsetMarker extends TNext['_input_in']
40	    ? TPrev['_input_in']
41	    : Overwrite<TPrev['_input_in'], TNext['_input_in']>;
42	  _input_out: UnsetMarker extends TNext['_input_out']
43	    ? TPrev['_input_out']
44	    : Overwrite<TPrev['_input_out'], TNext['_input_out']>;
45	  _output_in: FallbackValue<TNext['_output_in'], TPrev['_output_in']>;
46	  _output_out: FallbackValue<TNext['_output_out'], TPrev['_output_out']>;
47	}>;
48	
49	/**
50	 * @internal
51	 */
52	export interface BuildProcedure<
53	  TType extends ProcedureType,
54	  TParams extends ProcedureParams,
55	  TOutput,
56	> extends Procedure<
57	    TType,
58	    UnsetMarker extends TParams['_output_out']
59	      ? OverwriteKnown<
60	          TParams,
61	          {
62	            _output_in: TOutput;
63	            _output_out: TOutput;
64	          }
65	        >
66	      : TParams
67	  > {}
68	
69	type OverwriteIfDefined<TType, TWith> = UnsetMarker extends TType
70	  ? TWith
71	  : Simplify<TType & TWith>;
72	
73	type ErrorMessage<TMessage extends string> = TMessage;
74	
75	export type ProcedureBuilderDef<TParams extends ProcedureParams> = {
76	  inputs: Parser[];
77	  output?: Parser;
78	  meta?: TParams['_meta'];
79	  resolver?: ProcedureBuilderResolver;
80	  middlewares: ProcedureBuilderMiddleware[];
81	  mutation?: boolean;
82	  query?: boolean;
83	  subscription?: boolean;
84	};
85	
86	export type AnyProcedureBuilderDef = ProcedureBuilderDef<any>;
87	
88	export interface ProcedureBuilder<TParams extends ProcedureParams> {
89	  /**
90	   * Add an input parser to the procedure.
91	   */
92	  input<$Parser extends Parser>(
93	    schema: TParams['_input_out'] extends UnsetMarker
94	      ? $Parser
95	      : inferParser<$Parser>['out'] extends Record<string, unknown> | undefined
96	      ? TParams['_input_out'] extends Record<string, unknown> | undefined
97	        ? undefined extends inferParser<$Parser>['out'] // if current is optional the previous must be too
98	          ? undefined extends TParams['_input_out']
99	            ? $Parser
100	            : ErrorMessage<'Cannot chain an optional parser to a required parser'>
101	          : $Parser
102	        : ErrorMessage<'All input parsers did not resolve to an object'>
103	      : ErrorMessage<'All input parsers did not resolve to an object'>,
104	  ): ProcedureBuilder<{
105	    _config: TParams['_config'];
106	    _meta: TParams['_meta'];
107	    _ctx_out: TParams['_ctx_out'];
108	    _input_in: OverwriteIfDefined<
109	      TParams['_input_in'],
110	      inferParser<$Parser>['in']
111	    >;
112	    _input_out: OverwriteIfDefined<
113	      TParams['_input_out'],
114	      inferParser<$Parser>['out']
115	    >;
116	
117	    _output_in: TParams['_output_in'];
118	    _output_out: TParams['_output_out'];
119	  }>;
120	  /**
121	   * Add an output parser to the procedure.
122	   */
123	  output<$Parser extends Parser>(
124	    schema: $Parser,
125	  ): ProcedureBuilder<{
126	    _config: TParams['_config'];
127	    _meta: TParams['_meta'];
128	    _ctx_out: TParams['_ctx_out'];
129	    _input_in: TParams['_input_in'];
130	    _input_out: TParams['_input_out'];
131	    _output_in: inferParser<$Parser>['in'];
132	    _output_out: inferParser<$Parser>['out'];
133	  }>;
134	  /**
135	   * Add a meta data to the procedure.
136	   */
137	  meta(meta: TParams['_meta']): ProcedureBuilder<TParams>;
138	  /**
139	   * Add a middleware to the procedure.
140	   */
141	  use<$Params extends ProcedureParams>(
142	    fn:
143	      | MiddlewareBuilder<TParams, $Params>
144	      | MiddlewareFunction<TParams, $Params>,
145	  ): CreateProcedureReturnInput<TParams, $Params>;
146	  /**
147	   * Extend the procedure with another procedure.
148	   * @warning The TypeScript inference fails when chaining concatenated procedures.
149	   */
150	  unstable_concat<$ProcedureBuilder extends AnyProcedureBuilder>(
151	    proc: $ProcedureBuilder,
152	  ): $ProcedureBuilder extends ProcedureBuilder<infer $TParams>
153	    ? CreateProcedureReturnInput<TParams, $TParams>
154	    : never;
155	  /**
156	   * Query procedure
157	   */
158	  query<$Output>(
159	    resolver: (
160	      opts: ResolveOptions<TParams>,
161	    ) => MaybePromise<FallbackValue<TParams['_output_in'], $Output>>,
162	  ): BuildProcedure<'query', TParams, $Output>;
163	
164	  /**
165	   * Mutation procedure
166	   */
167	  mutation<$Output>(
168	    resolver: (
169	      opts: ResolveOptions<TParams>,
170	    ) => MaybePromise<FallbackValue<TParams['_output_in'], $Output>>,
171	  ): BuildProcedure<'mutation', TParams, $Output>;
172	
173	  /**
174	   * Mutation procedure
175	   */
176	  subscription<$Output>(
177	    resolver: (
178	      opts: ResolveOptions<TParams>,
179	    ) => MaybePromise<FallbackValue<TParams['_output_in'], $Output>>,
180	  ): BuildProcedure<'subscription', TParams, $Output>;
181	  /**
182	   * @internal
183	   */
184	  _def: ProcedureBuilderDef<TParams>;
185	}
186	
187	type AnyProcedureBuilder = ProcedureBuilder<any>;
188	
189	export type ProcedureBuilderMiddleware = MiddlewareFunction<any, any>;
190	
191	export type ProcedureBuilderResolver = (
192	  opts: ResolveOptions<any>,
193	) => Promise<unknown>;
194	
195	function createNewBuilder(
196	  def1: AnyProcedureBuilderDef,
197	  def2: Partial<AnyProcedureBuilderDef>,
198	) {
199	  const { middlewares = [], inputs, meta, ...rest } = def2;
200	
201	  // TODO: maybe have a fn here to warn about calls
202	  return createBuilder({
203	    ...mergeWithoutOverrides(def1, rest),
204	    inputs: [...def1.inputs, ...(inputs ?? [])],
205	    middlewares: [...def1.middlewares, ...middlewares],
206	    meta: def1.meta && meta ? { ...def1.meta, ...meta } : meta ?? def1.meta,
207	  });
208	}
209	
210	export function createBuilder<TConfig extends AnyRootConfig>(
211	  initDef: Partial<AnyProcedureBuilderDef> = {},
212	): ProcedureBuilder<{
213	  _config: TConfig;
214	  _ctx_out: TConfig['$types']['ctx'];
215	  _input_in: UnsetMarker;
216	  _input_out: UnsetMarker;
217	  _output_in: UnsetMarker;
218	  _output_out: UnsetMarker;
219	  _meta: TConfig['$types']['meta'];
220	}> {
221	  const _def: AnyProcedureBuilderDef = {
222	    inputs: [],
223	    middlewares: [],
224	    ...initDef,
225	  };
226	
227	  return {
228	    _def,
229	    input(input) {
230	      const parser = getParseFn(input);
231	      return createNewBuilder(_def, {
232	        inputs: [input],
233	        middlewares: [createInputMiddleware(parser)],
234	      }) as AnyProcedureBuilder;
235	    },
236	    output(output: Parser) {
237	      const parseOutput = getParseFn(output);
238	      return createNewBuilder(_def, {
239	        output,
240	        middlewares: [createOutputMiddleware(parseOutput)],
241	      }) as AnyProcedureBuilder;
242	    },
243	    meta(meta) {
244	      return createNewBuilder(_def, {
245	        meta: meta as Record<string, unknown>,
246	      }) as AnyProcedureBuilder;
247	    },
248	    /**
249	     * @deprecated
250	     * This functionality is deprecated and will be removed in the next major version.
251	     */
252	    unstable_concat(builder) {
253	      return createNewBuilder(_def, builder._def) as any;
254	    },
255	    use(middlewareBuilderOrFn) {
256	      // Distinguish between a middleware builder and a middleware function
257	      const middlewares =
258	        '_middlewares' in middlewareBuilderOrFn
259	          ? middlewareBuilderOrFn._middlewares
260	          : [middlewareBuilderOrFn];
261	
262	      return createNewBuilder(_def, {
263	        middlewares: middlewares as ProcedureBuilderMiddleware[],
264	      }) as AnyProcedureBuilder;
265	    },
266	    query(resolver) {
267	      return createResolver(
268	        { ..._def, query: true },
269	        resolver,
270	      ) as AnyQueryProcedure;
271	    },
272	    mutation(resolver) {
273	      return createResolver(
274	        { ..._def, mutation: true },
275	        resolver,
276	      ) as AnyMutationProcedure;
277	    },
278	    subscription(resolver) {
279	      return createResolver(
280	        { ..._def, subscription: true },
281	        resolver,
282	      ) as AnySubscriptionProcedure;
283	    },
284	  };
285	}
286	
287	function createResolver(
288	  _def: AnyProcedureBuilderDef,
289	  resolver: (opts: ResolveOptions<any>) => MaybePromise<any>,
290	) {
291	  const finalBuilder = createNewBuilder(_def, {
292	    resolver,
293	    middlewares: [
294	      async function resolveMiddleware(opts) {
295	        const data = await resolver(opts);
296	        return {
297	          marker: middlewareMarker,
298	          ok: true,
299	          data,
300	          ctx: opts.ctx,
301	        } as const;
302	      },
303	    ],
304	  });
305	
306	  return createProcedureCaller(finalBuilder._def);
307	}
308	
309	/**
310	 * @internal
311	 */
312	export interface ProcedureCallOptions {
313	  ctx: unknown;
314	  rawInput: unknown;
315	  input?: unknown;
316	  path: string;
317	  type: ProcedureType;
318	}
319	
320	const codeblock = `
321	If you want to call this function on the server, you do the following:
322	This is a client-only function.
323	
324	const caller = appRouter.createCaller({
325	  /* ... your context */
326	});
327	
328	const result = await caller.call('myProcedure', input);
329	`.trim();
330	
331	function createProcedureCaller(_def: AnyProcedureBuilderDef): AnyProcedure {
332	  const procedure = async function resolve(opts: ProcedureCallOptions) {
333	    // is direct server-side call
334	    if (!opts || !('rawInput' in opts)) {
335	      throw new Error(codeblock);
336	    }
337	
338	    // run the middlewares recursively with the resolver as the last one
339	    const callRecursive = async (
340	      callOpts: {
341	        ctx: any;
342	        index: number;
343	        input?: unknown;
344	        rawInput?: unknown;
345	      } = {
346	        index: 0,
347	        ctx: opts.ctx,
348	      },
349	    ): Promise<MiddlewareResult<any>> => {
350	      try {
351	        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
