268	    try {
269	      const data = await parse(result.data);
270	      return {
271	        ...result,
272	        data,
273	      };
274	    } catch (cause) {
275	      throw new TRPCError({
276	        message: 'Output validation failed',
277	        code: 'INTERNAL_SERVER_ERROR',
278	        cause,
279	      });
280	    }
281	  };
282	  outputMiddleware._type = 'output';
283	  return outputMiddleware;
284	}
